create extension if not exists pgcrypto;
create schema if not exists private;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique not null check(char_length(username) between 3 and 24),avatar_url text,bio text check(char_length(coalesce(bio,''))<=280),role text not null default 'user' check(role in ('user','moderator','admin')),is_banned boolean not null default false,created_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,icon text not null default 'map-pin',color text not null default '#65e0cf',sort_order int not null default 100,is_active boolean not null default true,created_at timestamptz not null default now());
create table public.map_locations(id uuid primary key default gen_random_uuid(),title text not null,description text not null default '',category_id uuid references public.categories(id) on delete set null,x double precision not null check(x between 0 and 1),y double precision not null check(y between 0 and 1),source_type text not null default 'community' check(source_type in ('official_reference','editorial','community')),verification_status text not null default 'unverified' check(verification_status in ('unverified','community_verified','admin_confirmed')),source_url text,created_by uuid references public.profiles(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.discoveries(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,category_id uuid not null references public.categories(id),title text not null check(char_length(title) between 3 and 100),description text not null check(char_length(description) between 10 and 2000),x double precision not null check(x between 0 and 1),y double precision not null check(y between 0 and 1),image_url text,external_url text,tags text[] not null default '{}',verification_status text not null default 'unverified' check(verification_status in ('unverified','in_review','community_verified','admin_confirmed')),moderation_status text not null default 'published' check(moderation_status in ('published','hidden','removed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.comments(id uuid primary key default gen_random_uuid(),discovery_id uuid not null references public.discoveries(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,body text not null check(char_length(body) between 1 and 1000),created_at timestamptz not null default now());
create table public.likes(discovery_id uuid not null references public.discoveries(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(discovery_id,user_id));
create table public.reports(id uuid primary key default gen_random_uuid(),discovery_id uuid not null references public.discoveries(id) on delete cascade,reporter_id uuid not null references public.profiles(id) on delete cascade,reason text not null check(char_length(reason) between 5 and 500),status text not null default 'open' check(status in ('open','reviewed','dismissed','actioned')),created_at timestamptz not null default now(),unique(discovery_id,reporter_id));
create table public.followers(follower_id uuid not null references public.profiles(id) on delete cascade,followed_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(follower_id,followed_id),check(follower_id<>followed_id));
create index discoveries_created_idx on public.discoveries(created_at desc);create index discoveries_category_idx on public.discoveries(category_id);create index discoveries_map_idx on public.discoveries(x,y);create index comments_discovery_idx on public.comments(discovery_id,created_at desc);create index locations_category_idx on public.map_locations(category_id);
create or replace function private.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ declare requested_username text; begin requested_username:=coalesce(new.raw_user_meta_data->>'username','player_'||substr(new.id::text,1,8));insert into public.profiles(id,username) values(new.id,requested_username) on conflict(id) do nothing;return new;end;$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure private.handle_new_user();revoke all on function private.handle_new_user() from public,anon,authenticated;
create or replace function public.is_admin() returns boolean language sql stable security invoker set search_path='' as $$ select exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','moderator') and not p.is_banned); $$;
alter table public.profiles enable row level security;alter table public.categories enable row level security;alter table public.map_locations enable row level security;alter table public.discoveries enable row level security;alter table public.comments enable row level security;alter table public.likes enable row level security;alter table public.reports enable row level security;alter table public.followers enable row level security;
create policy "profiles are public" on public.profiles for select to anon,authenticated using(true);
create policy "profile owner updates safe fields" on public.profiles for update to authenticated using((select auth.uid())=id) with check((select auth.uid())=id and role='user' and is_banned=false);
create policy "categories are public" on public.categories for select to anon,authenticated using(is_active or public.is_admin());
create policy "admins manage categories" on public.categories for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "locations are public" on public.map_locations for select to anon,authenticated using(true);
create policy "admins manage locations" on public.map_locations for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "published discoveries are public" on public.discoveries for select to anon,authenticated using(moderation_status='published' or user_id=(select auth.uid()) or public.is_admin());
create policy "signed in users create discoveries" on public.discoveries for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and not p.is_banned));
create policy "owners update own discoveries" on public.discoveries for update to authenticated using(user_id=(select auth.uid()) or public.is_admin()) with check((user_id=(select auth.uid()) and moderation_status='published') or public.is_admin());
create policy "owners or admins delete discoveries" on public.discoveries for delete to authenticated using(user_id=(select auth.uid()) or public.is_admin());
create policy "comments public read" on public.comments for select to anon,authenticated using(true);
create policy "signed in users comment" on public.comments for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and not p.is_banned));
create policy "comment owner or admin delete" on public.comments for delete to authenticated using(user_id=(select auth.uid()) or public.is_admin());
create policy "likes public read" on public.likes for select to anon,authenticated using(true);
create policy "users manage own likes" on public.likes for insert to authenticated with check(user_id=(select auth.uid()));
create policy "users remove own likes" on public.likes for delete to authenticated using(user_id=(select auth.uid()));
create policy "reports private to reporter and moderators" on public.reports for select to authenticated using(reporter_id=(select auth.uid()) or public.is_admin());
create policy "signed in users report" on public.reports for insert to authenticated with check(reporter_id=(select auth.uid()));
create policy "moderators manage reports" on public.reports for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "followers public read" on public.followers for select to anon,authenticated using(true);
create policy "users follow others" on public.followers for insert to authenticated with check(follower_id=(select auth.uid()));
create policy "users unfollow" on public.followers for delete to authenticated using(follower_id=(select auth.uid()));
grant usage on schema public to anon,authenticated;
grant select on public.categories,public.map_locations,public.discoveries,public.comments,public.likes,public.profiles,public.followers to anon,authenticated;
grant insert,update,delete on public.profiles to authenticated;grant insert,update,delete on public.discoveries to authenticated;grant insert,delete on public.comments,public.likes,public.followers to authenticated;grant insert,select,update on public.reports to authenticated;grant insert,update,delete,select on public.categories,public.map_locations to authenticated;
insert into public.categories(name,slug,icon,color,sort_order) values('Città e quartieri','districts','map','#62c6d8',10),('Negozi e attività','businesses','store','#e5b45d',20),('Ristoranti e bar','food','utensils','#f28b70',30),('Servizi pubblici','services','building-2','#75a9e8',40),('Trasporti','transport','car-front','#a78bfa',50),('Luoghi speciali','landmarks','star','#f0d36d',60),('Segreti e collezionabili','secrets','sparkles','#65e0cf',70),('Scoperte varie','other','map-pin','#c0cbd5',80) on conflict(slug) do nothing;